sql.where:
AND EXISTS (
    SELECT 1 FROM outlet tenant_outlet
    WHERE tenant_outlet.id = po.outlet_id
      AND tenant_outlet.vendor_id = #{q.vendorId}
      AND tenant_outlet.deleted_at IS NULL
)

    AND po.status IN ('OPEN', 'SENT', 'PARTIALLY_RECEIVED')


    AND po.status = #{q.status}


    AND po.type = #{q.type}


    AND po.from_id = #{q.supplierId}


    AND po.to_id = #{q.transferorId}


    AND po.to_id = #{q.outletId}


    AND po.invoice_number LIKE CONCAT('%', #{q.invoiceNumber}, '%')


    AND po.reference LIKE CONCAT('%', #{q.reference}, '%')


    AND po.order_date = #{q.orderDate}


    AND po.order_date >= #{q.orderDateFrom}


    AND po.order_date <= #{q.orderDateTo}


    AND po.due_date = #{q.dueDate}


    AND po.created_by_id = #{q.createdById}


    AND po.sent_by_id = #{q.sentById}


    AND po.received_by_id = #{q.receivedById}


    AND EXISTS (
        SELECT 1 FROM order_product op
        WHERE op.order_id = po.id AND op.product_id = #{q.productId}
    )

mapper.select:

WHERE po.id = #{id}
  AND EXISTS (
      SELECT 1 FROM outlet tenant_outlet
      WHERE tenant_outlet.id = po.outlet_id
        AND tenant_outlet.vendor_id = #{vendorId}
        AND tenant_outlet.deleted_at IS NULL
  )
